package com.smarthire.backend.platform.ai;
import org.aspectj.lang.ProceedingJoinPoint; import org.aspectj.lang.annotation.Around; import org.aspectj.lang.annotation.Aspect; import org.springframework.stereotype.Component;
@Aspect @Component public class AiUsageMetricsAspect { private final AiUsageMetricsService metrics; public AiUsageMetricsAspect(AiUsageMetricsService metrics){this.metrics=metrics;} @Around("within(com.smarthire.backend.interview.ai..*) || within(com.smarthire.backend.resume.ai..*) || within(com.smarthire.backend.ai.speech..*) || within(com.smarthire.backend.ai.emotion..*) || within(com.smarthire.backend.ai.eye..*) || within(com.smarthire.backend.ai.technical..*)") public Object record(ProceedingJoinPoint p)throws Throwable{long start=System.nanoTime(); boolean ok=false; try{Object r=p.proceed();ok=true;return r;}finally{metrics.record(p.getSignature().getDeclaringType().getSimpleName(),p.getSignature().getName(),ok,(System.nanoTime()-start)/1_000_000);}}}
